# _EXPECTED_BLOB and _EXTRACTS are populated by solution/rebuild_fixtures.py.
# Each is a zlib+base64 blob. Do NOT hand-edit.
_EXPECTED_BLOB = ''

_EXTRACTS = {
    'A': '',
    'B': '',
}


_ENV = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C.UTF-8",
        "HOME": "/tmp", "PYTHONHASHSEED": "0"}
_LOBS = ["wc", "cal", "gl", "cp", "spec"]
_ARTIFACTS = [
    "summary.json", "methodology_audit.json", "data_quality.json",
    "lob_wc.json", "lob_cal.json", "lob_gl.json", "lob_cp.json", "lob_spec.json",
    "treaty_working.json",
]
_CYCLES = ["H%02d" % i for i in range(1, 27)]
_LAYERS = ["retention", "working_excess", "cat_excess"]
_CACHE = {}


def _safe(action):
    try:
        return bool(action())
    except Exception:
        return False


def _int_eq(a, b) -> bool:
    if isinstance(a, bool) or isinstance(b, bool):
        return False
    if not isinstance(a, int) or not isinstance(b, int):
        return False
    return a == b


def _str_eq(a, b) -> bool:
    return isinstance(a, str) and isinstance(b, str) and a == b


def _int_str(v) -> str:
    if isinstance(v, bool) or not isinstance(v, int):
        return "NONINT"
    return str(v)


def _diff_str(a, b) -> str:
    if isinstance(a, bool) or not isinstance(a, int):
        return "NONINT"
    if isinstance(b, bool) or not isinstance(b, int):
        return "NONINT"
    return str(a - b)


def _matches(out: Path, corpus: str, view_keys) -> bool:
    try:
        wanted = _expected().get(corpus, {}).get("digests", {})
    except Exception:
        return False
    if not wanted:
        return False
    found = _digests(out)
    for key in view_keys:
        if key not in wanted or key not in found:
            return False
        if found[key] != wanted[key]:
            return False
    return True


def _expected():
    if "expected" not in _CACHE:
        _CACHE["expected"] = json.loads(zlib.decompress(base64.b64decode(_EXPECTED_BLOB)))
    return _CACHE["expected"]


def _digest(lines):
    return hashlib.sha256("\n".join(lines).encode()).hexdigest()


def _views(out: Path):
    # Reads each LOB document in its shipped order and hashes views over the
    # ledger. The ledger is NOT re-sorted here: a module that emits rows in a
    # different order than the one output_contract.md declares will fail the
    # order check (ledger_order_exact) and still produce a digest, but the
    # digest will differ from the shipped digest because the view carries the
    # order.
    backbone, spine, layers, outcome, dollars, cells, order_view = [], [], [], [], [], [], []
    for lob in _LOBS:
        d = json.loads((out / f"lob_{lob}.json").read_text())
        ledger = d.get("ledger", [])
        for i, row in enumerate(ledger):
            stem = "%s|%s|%s" % (lob, row.get("cycle",""), row.get("claim_ref",""))
            backbone.append("%s|%s|%s|%s|%s" % (
                stem, row.get("reinsurer_canonical","") or "",
                row.get("layer",""), _int_str(row.get("ultimate", 0)),
                _int_str(row.get("paid_to_date", 0))))
            spine.append("%s|%s|%s|%s" % (
                stem, _int_str(row.get("ceded_hours", 0)), _int_str(row.get("alae", 0)),
                _diff_str(row.get("ultimate", 0), row.get("paid_to_date", 0))))
            layers.append("%s|%s" % (stem, row.get("layer","")))
            outcome.append("%s|%s|%s" % (stem, row.get("outcome",""), row.get("reason","")))
            dollars.append("%s|%s|%s|%s" % (
                stem, _int_str(row.get("paid_to_date", 0)), _int_str(row.get("ultimate", 0)),
                _int_str(row.get("ceded_hours", 0))))
            order_view.append("%s|%d|%s|%s" % (
                lob, i, row.get("cycle",""),
                (row.get("reinsurer_canonical","") or "") + "|" + row.get("claim_ref","")))
        for cycle in _CYCLES:
            cap_map = d.get("capacity_per_cycle", {})
            ceil_map = d.get("ceiling_per_cycle", {})
            rem_map = d.get("remainder_dollars_per_cycle", {})
            cells.append("%s|%s|%s|%s|%s" % (
                lob, cycle,
                _int_str(cap_map.get(cycle, 0) if isinstance(cap_map, dict) else None),
                _int_str(ceil_map.get(cycle, 0) if isinstance(ceil_map, dict) else None),
                _int_str(rem_map.get(cycle, 0) if isinstance(rem_map, dict) else None)))
    return {"ledger_backbone": backbone, "ledger_spine": spine,
            "ledger_layers": layers, "ledger_outcome": outcome,
            "ledger_dollars": dollars, "cells": cells,
            "ledger_order": order_view}


def _digests(out: Path):
    return {name: _digest(lines) for name, lines in _views(out).items()}


def _module(workspace: Path) -> Path:
    return Path(workspace) / "out" / "reserving.py"


def _delivered(workspace: Path) -> Path:
    return Path(workspace) / "out"


def _source(workspace: Path) -> str:
    return _module(workspace).read_text(errors="replace")


def _unpack(corpus: str, target: Path) -> None:
    data = _EXTRACTS.get(corpus, "")
    if not data or data.startswith("__"):
        raise RuntimeError("extract %s not sealed" % corpus)
    raw = zlib.decompress(base64.b64decode(data))
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r") as archive:
        archive.extractall(target)


def _shuffle_rows(directory: Path) -> None:
    for path in sorted(directory.iterdir()):
        if path.suffix not in {".csv", ".tsv", ".jsonl"}:
            continue
        lines = path.read_text().splitlines()
        if path.suffix in {".csv", ".tsv"}:
            if len(lines) < 4:
                continue
            header, body = lines[0], lines[1:]
        else:
            header, body = None, lines
            if len(body) < 4:
                continue
        middle = len(body) // 2
        rotated = body[middle:] + body[:middle]
        new = ([header] + rotated) if header is not None else rotated
        path.write_text("\n".join(new) + "\n")


def _run(workspace: Path, tag: str):
    if tag in _CACHE:
        return _CACHE[tag]
    corpus = tag.split("_")[0]
    result = {"code": -1, "out": None, "data": None, "before": {}, "after": {},
              "artifact_bytes": {}, "artifact_bytes_rerun": {}}
    module = _module(workspace)
    if not module.is_file():
        _CACHE[tag] = result
        return result
    room = tempfile.mkdtemp(prefix="hold_")
    name = "corpus_%s" % tag.lower() if tag.endswith("named") else "data"
    data = Path(room) / name
    data.mkdir(parents=True, exist_ok=True)
    try:
        _unpack(corpus, data)
    except Exception:
        _CACHE[tag] = result
        return result
    if tag.endswith("perm"):
        _shuffle_rows(data)
    if tag.endswith("missing"):
        victim = data / "cession_q3.tsv"
        if victim.is_file():
            victim.unlink()
    out = Path(room) / "out"
    out.mkdir(parents=True, exist_ok=True)
    copy = Path(room) / "reserving.py"
    shutil.copy2(module, copy)
    os.chmod(copy, 0o755)
    for path in sorted(data.iterdir()):
        if path.is_file():
            result["before"][path.name] = hashlib.sha256(path.read_bytes()).hexdigest()
    command = [sys.executable, "-I", str(copy), "--data", str(data), "--out", str(out)]
    process = None
    try:
        process = subprocess.Popen(command, cwd=room, env=dict(_ENV),
                                   stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                   start_new_session=True)
        try:
            process.communicate(timeout=500)
        except subprocess.TimeoutExpired:
            try:
                os.killpg(os.getpgid(process.pid), signal.SIGKILL)
            except (ProcessLookupError, PermissionError):
                pass
            process.communicate()
        result["code"] = process.returncode
    except Exception:
        result["code"] = -1
    finally:
        if process is not None:
            try:
                os.killpg(os.getpgid(process.pid), signal.SIGKILL)
            except (ProcessLookupError, PermissionError):
                pass
    for path in sorted(data.iterdir()):
        if path.is_file():
            result["after"][path.name] = hashlib.sha256(path.read_bytes()).hexdigest()
    for name in _ARTIFACTS:
        p = out / name
        if p.is_file():
            result["artifact_bytes"][name] = p.read_bytes()
    result["out"] = out
    result["data"] = data
    _CACHE[tag] = result
    return result


def _rerun_bytes(workspace: Path, tag: str):
    first = _run(workspace, tag)
    second_tag = tag + "_byte_rerun"
    if second_tag in _CACHE:
        return first, _CACHE[second_tag]
    room = tempfile.mkdtemp(prefix="hold_rerun_")
    data = Path(room) / "data"
    data.mkdir(parents=True, exist_ok=True)
    try:
        _unpack(tag.split("_")[0], data)
    except Exception:
        _CACHE[second_tag] = {}
        return first, {}
    out = Path(room) / "out"
    out.mkdir(parents=True, exist_ok=True)
    copy = Path(room) / "reserving.py"
    shutil.copy2(_module(workspace), copy)
    os.chmod(copy, 0o755)
    command = [sys.executable, "-I", str(copy), "--data", str(data), "--out", str(out)]
    process = None
    try:
        process = subprocess.Popen(command, cwd=room, env=dict(_ENV),
                                   stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                   start_new_session=True)
        try:
            process.communicate(timeout=500)
        except subprocess.TimeoutExpired:
            try:
                os.killpg(os.getpgid(process.pid), signal.SIGKILL)
            except (ProcessLookupError, PermissionError):
                pass
            process.communicate()
    except Exception:
        pass
    finally:
        if process is not None:
            try:
                os.killpg(os.getpgid(process.pid), signal.SIGKILL)
            except (ProcessLookupError, PermissionError):
                pass
    rerun = {}
    for name in _ARTIFACTS:
        p = out / name
        if p.is_file():
            rerun[name] = p.read_bytes()
    _CACHE[second_tag] = rerun
    return first, rerun


def _complete(out) -> bool:
    return out is not None and all((out / name).is_file() for name in _ARTIFACTS)


def _literals(workspace: Path):
    tree = ast.parse(_source(workspace))
    numbers = set()
    strings = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant):
            if isinstance(node.value, int) and not isinstance(node.value, bool):
                numbers.add(node.value)
            elif isinstance(node.value, str):
                strings.append(node.value)
    return numbers, strings


