def development_spine_exact(workspace: Path) -> bool:
    def body():
        out = _delivered(workspace)
        shipped = _expected()["shipped"]
        return _digest(_views(out)["ledger_backbone"]) == shipped["digests"]["ledger_backbone"]
    return _safe(body)


