@criterion(description="Every artifact is serialised with sort_keys=True, indent=1, UTF-8 without BOM and a single trailing newline.")
def exact_serialization_format(workspace: Path) -> bool:
    def body():
        out = _delivered(workspace)
        for name in _ARTIFACTS:
            p = out / name
            if not p.is_file():
                return False
            raw = p.read_bytes()
            if raw.startswith(b"\xef\xbb\xbf"):
                return False
            text = raw.decode("utf-8")
            if not text.endswith("\n") or text.endswith("\n\n"):
                return False
            obj = json.loads(text)
            canonical = json.dumps(obj, sort_keys=True, indent=1, ensure_ascii=False) + "\n"
            if text != canonical:
                return False
        return True
    return _safe(body)


# NEGATIVE CHECKS
# Each registers once below and no two negatives penalise the same action.
# Fire conditions and documented penalties are listed above each check.


# Fires when the delivered module hardcodes any sealed scalar as a Python
# integer literal, or embeds any sealed sha256 digest as a string literal.
# Excludes scalars that are small integers reused by the task's own
# vocabulary (such as 0, 1, 2, 3, 26) to avoid false positives.
@criterion(description="The module hardcodes answers from the shipped corpus as literals.")
def negative_hardcoded_sample_answers(workspace: Path) -> bool:
    def body():
        if not _module(workspace).is_file():
            return False
        numbers, strings = _literals(workspace)
        shipped = _expected()["shipped"]
        marks = {shipped["scalars"].get(k) for k in
                 ("total_ceded", "total_ultimate", "total_paid_to_date",
                  "treaty_ceded_total", "treaty_retention",
                  "treaty_working_excess", "treaty_cat_excess")}
        marks = {m for m in marks if isinstance(m, int) and m > 1000}
        if marks & numbers:
            return True
        hexes = set(shipped.get("digests", {}).values())
        if any(v in hexes for v in strings):
            return True
        banned_literal_strings = {"2032-07-01T00:00:00Z"}
        if any(v in banned_literal_strings for v in strings):
            return True
        return False
    return _safe(body)


# Fires when the module embeds thousands of bytes of corpus content as a
# string literal (used as a shortcut around reading the shipped data).
@criterion(description="The module embeds corpus records inside itself, so it answers from a copy rather than the corpus it is given.")
def negative_embedded_corpus_rows(workspace: Path) -> bool:
    def body():
        if not _module(workspace).is_file():
            return False
        _nums, strings = _literals(workspace)
        marks = ("CLM-00", "RE-0", "AY20")
        for v in strings:
            if len(v) > 4000 and sum(v.count(m) for m in marks) >= 10:
                return True
        text = _source(workspace)
        return sum(text.count(m) for m in marks) > 60
    return _safe(body)


# Fires when the module returns the same ledger for two different corpora,
# which proves the output is independent of the input. Pairs with
# program_reproduces_unseen_extract_beta on the positive side.
@criterion(description="The module returns the same ledger for two different corpora, so output is independent of input.")
def negative_output_independent_of_the_corpus(workspace: Path) -> bool:
    def body():
        first = _run(workspace, "A")
        second = _run(workspace, "B")
        if first["code"] != 0 or second["code"] != 0:
            return False
        if not _complete(first["out"]) or not _complete(second["out"]):
            return False
        return _digests(first["out"]) == _digests(second["out"])
    return _safe(body)


# Fires when the module changes its answer when the corpus directory is
# renamed, which proves it reads a hardcoded path somewhere.
@criterion(description="The module depends on the directory name it reads, so a renamed corpus yields other figures.")
def negative_module_reads_a_fixed_corpus_path(workspace: Path) -> bool:
    def body():
        plain = _run(workspace, "A")
        renamed = _run(workspace, "A_named")
        if plain["code"] != 0 or not _complete(plain["out"]):
            return False
        if renamed["code"] != 0 or not _complete(renamed["out"]):
            return True
        return _digests(renamed["out"]) != _digests(plain["out"])
    return _safe(body)


# Fires when the module hides a missing source behind a quiet exit.
# instruction.md explicitly requires FileNotFoundError on missing sources.
@criterion(description="The module hides a missing source behind a quiet exit, so a short corpus still yields a full report.")
def negative_silent_recovery_from_missing_source(workspace: Path) -> bool:
    def body():
        if not _module(workspace).is_file():
            return False
        result = _run(workspace, "A_missing")
        if result["code"] != 0 or not _complete(result["out"]):
            return False
        return _matches(result["out"], "A", ["ledger_backbone"])
    return _safe(body)


# Fires when the module writes to the corpus directory it reads, which
# would mutate the evidence under it.
@criterion(description="The module writes into the corpus directory it reads, mutating the evidence under it.")
def negative_module_mutates_the_corpus(workspace: Path) -> bool:
    def body():
        result = _run(workspace, "A")
        if result["code"] != 0 or not result["before"]:
            return False
        return result["before"] != result["after"]
    return _safe(body)


# Fires when the module imports a network module or shells out to another
# process. `http.HTTPStatus` and other stdlib submodules that make no
# network call are intentionally not banned here.
@criterion(description="The module opens the network or shells out to another process instead of deriving locally.")
def negative_module_opens_network_or_shells_out(workspace: Path) -> bool:
    def body():
        if not _module(workspace).is_file():
            return False
        tree = ast.parse(_source(workspace))
        banned_imports = {"socket", "urllib", "requests", "ftplib", "telnetlib", "pty"}
        banned_http = {"http.client", "http.server", "urllib.request"}
        shell_attrs = {"system", "popen", "spawnv", "execv"}
        subprocess_calls = {"run", "Popen", "call", "check_call", "check_output", "getoutput", "getstatusoutput"}
        os_names = {"os"}
        subprocess_names = {"subprocess"}
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for a in node.names:
                    if a.name == "os" and a.asname:
                        os_names.add(a.asname)
                    if a.name == "subprocess" and a.asname:
                        subprocess_names.add(a.asname)
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for a in node.names:
                    top = a.name.split(".")[0]
                    if top in banned_imports:
                        return True
                    if a.name in banned_http:
                        return True
            elif isinstance(node, ast.ImportFrom):
                top = (node.module or "").split(".")[0]
                if top in banned_imports:
                    return True
                if node.module in banned_http:
                    return True
                if node.module == "os" and any(a.name in shell_attrs for a in node.names):
                    return True
                if node.module == "subprocess" and any(a.name in subprocess_calls for a in node.names):
                    return True
            elif isinstance(node, ast.Attribute):
                owner = node.value
                if isinstance(owner, ast.Name):
                    if node.attr in shell_attrs and owner.id in os_names:
                        return True
                    if node.attr in subprocess_calls and owner.id in subprocess_names:
                        return True
        return False
    return _safe(body)


